Spend, sum(ifnull(content_spend, 0)) AS Content_Spend, sum(ifnull(influencer_spend, 0)) AS Influencer_Spend, SUM(IFNULL(shopify_spend_alia, 0)) + SUM(IFNULL(software_spend_K_O, 0)) AS CRM_Retention_Cost, sum(ifnull(Porter_logistic_cost, 0)) AS Porter_logistic_cost, sum(ifnull(Weight_amount, 0)) AS RTO_Charge, ( sum(ifnull(selling_price, 0)) - sum(ifnull(CASE WHEN lower(order_status) LIKE \'%cancel%\' THEN selling_price END, 0)) - sum(ifnull(total_return_amount, 0)) - SUM(IFNULL(CASE WHEN NOT LOWER(order_status) LIKE \'%cancel%\' THEN tax END, 0)) ) - SUM( CASE WHEN LOWER(marketplace) <> \'offline\' OR marketplace IS NULL THEN IFNULL(total_cogs, 0) ELSE 0 END ) - SUM(CASE WHEN LOWER(marketplace) = \'offline\' THEN IFNULL(total_cogs, 0) ELSE 0 END) - ABS(SUM(IFNULL(amazon_commission_charge, 0))) - ( SUM(IFNULL(shopify_spend, 0)) * 0.02 ) * ( 1 - 0.18 ) - sum(ifnull(Blinkit_commission_Charge, 0)) - sum(ifnull(Blinkit_shipping_Charge, 0)) - sum(ifnull(Blinkit_storage_Charge, 0)) - ABS(SUM(IFNULL(amazon_shipping_charge, 0))) - sum(ifnull(freight_charge, 0)) - sum(ifnull(cod_charge, 0)) - sum(ifnull(marketing_spend, 0)) - sum(ifnull(agency_spend, 0)) - sum(ifnull(content_spend, 0)) - sum(ifnull(influencer_spend, 0)) - SUM(IFNULL(shopify_spend_alia, 0)) - SUM(IFNULL(software_spend_K_O, 0)) - sum(ifnull(Porter_logistic_cost, 0)) - sum(ifnull(Weight_amount, 0)) AS CM2, SAFE_DIVIDE( ( sum(ifnull(selling_price, 0)) - sum(ifnull(CASE WHEN lower(order_status) LIKE \'%cancel%\' THEN selling_price END, 0)) - sum(ifnull(total_return_amount, 0)) - SUM(IFNULL(CASE WHEN NOT LOWER(order_status) LIKE \'%cancel%\' THEN tax END, 0)) ) - SUM( CASE WHEN LOWER(marketplace) <> \'offline\' OR marketplace IS NULL THEN IFNULL(total_cogs, 0) ELSE 0 END ) - SUM(CASE WHEN LOWER(marketplace) = \'offline\' THEN IFNULL(total_cogs, 0) ELSE 0 END) - ABS(SUM(IFNULL(amazon_commission_charge, 0))) - ( SUM(IFNULL(shopify_spend, 0)) * 0.02 ) * ( 1 - 0.18 ) - sum(ifnull(Blinkit_commission_Charge, 0)) - sum(if