) - sum(ifnull(CASE WHEN lower(order_status) LIKE \'%cancel%\' THEN selling_price END, 0)) - sum(ifnull(total_return_amount, 0)) - SUM(IFNULL(CASE WHEN NOT LOWER(order_status) LIKE \'%cancel%\' THEN tax END, 0)) ) - SUM( CASE WHEN LOWER(marketplace) <> \'offline\' OR marketplace IS NULL THEN IFNULL(total_cogs, 0) ELSE 0 END ) - SUM(CASE WHEN LOWER(marketplace) = \'offline\' THEN IFNULL(total_cogs, 0) ELSE 0 END) - ABS(SUM(IFNULL(amazon_commission_charge, 0))) - ( SUM(IFNULL(shopify_spend, 0)) * 0.02 ) * ( 1 - 0.18 ) - sum(ifnull(Blinkit_commission_Charge, 0)) - sum(ifnull(Blinkit_shipping_Charge, 0)) - sum(ifnull(Blinkit_storage_Charge, 0)) - ABS(SUM(IFNULL(amazon_shipping_charge, 0))) - sum(ifnull(freight_charge, 0)) - sum(ifnull(cod_charge, 0)) - sum(ifnull(marketing_spend, 0)) - sum(ifnull(agency_spend, 0)) - sum(ifnull(content_spend, 0)) - sum(ifnull(influencer_spend, 0)) - SUM(IFNULL(shopify_spend_alia, 0)) - SUM(IFNULL(software_spend_K_O, 0)) - sum(ifnull(Porter_logistic_cost, 0)) - sum(ifnull(Weight_amount, 0)) - sum(ifnull(website_growth, 0)) - sum(ifnull(software_spend, 0)), sum(ifnull(selling_price, 0)) - sum(ifnull(CASE WHEN lower(order_status) LIKE \'%cancel%\' THEN selling_price END, 0)) - sum(ifnull(total_return_amount, 0)) - SUM(IFNULL(CASE WHEN NOT LOWER(order_status) LIKE \'%cancel%\' THEN tax END, 0)) ) AS CM3__ FROM Maplemonk.atovio_pandl GROUP BY order_Date; CREATE OR REPLACE TABLE Maplemonk.Atovio_Profit_Loss_Category_Level AS SELECT order_Date, main_category_sort, main_category, sub_category_sort, sub_category, SUM(value) AS value FROM ( SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 1 AS main_category_sort, \'Revenue\' AS main_category, 1 AS sub_category_sort, \'MRP Sales\' AS sub_category, IFNULL(MRP_Sales,0) AS value FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 1, \'Revenue\', 2, \'Discount\', IFNULL(Discount,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 1, \'Revenue\', 3, \'Gross Sales\', IFNULL(Gross_Sales,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 1, \'Revenue\', 4, \'Cancellations\', IFNULL(Cancellations,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 1, \'Revenue\', 5, \'Returns\', IFNULL(Returns,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 1, \'Revenue\', 6, \'Taxes\', IFNULL(Total_Tax,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 1, \'Revenue\', 7, \'Net Sales\', IFNULL(Net_Sales,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 2, \'COGS\', 1, \'Sale Cogs\', IFNULL(Sale_Cogs,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 2, \'COGS\', 2, \'Promotional Cogs\', IFNULL(Promotional_COGS,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 2, \'COGS\', 3, \'Total Cogs\', (IFNULL(Sale_Cogs,0) +IFNULL(Promotional_COGS,0)) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 3, \'Commission\', 1, \'Amazon Commission\', ABS(IFNULL(Amazon_Commission,0)) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 3, \'Commission\', 2, \'Website Commission\', IFNULL(Website_Commission,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 3, \'Commission\', 3, \'Blinkit Commission\', IFNULL(Blinkit_Commission,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 3, \'Commission\', 4, \'Blinkit shipping\', IFNULL(Blinkit_Shipping,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 3, \'Commission\', 5, \'Blinkit Storage\', IFNULL(Blinkit_Storage,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 3, \'Logistics I\', 6, \'Amazon Shipping Charge\', ABS(IFNULL(amazon_shipping_charge,0)) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 3, \'Logistics I\', 7, \'Forward Shipping Charge\', IFNULL(Shipping_Charge,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 3, \'Logistics I\', 8, \'COD Charge\', IFNULL(COD_Charge,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 3, \'Logistics I\', 9, \'Total Logistics I \', ( ABS(IFNULL(Amazon_Commission,0)) + IFNULL(Website_Commission,0) + IFNULL(Blinkit_Commission,0) + IFNULL(Blinkit_Shipping,0) + IFNULL(Blinkit_Storage,0) + IFNULL(Shipping_Charge,0) + IFNULL(COD_Charge,0) + ABS(IFNULL(amazon_shipping_charge,0)) ) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 4, \'CM1\', 1, \'CM1\', IFNULL(CM1,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 4, \'CM1\', 2, \'CM1%\', SAFE_DIVIDE( SUM(IFNULL(CM1,0)), NULLIF(SUM(IFNULL(Net_Sales,0)),0) ) * 100 AS value FROM Maplemonk.Atovio_Profit_Loss_New GROUP BY 1 UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 5, \'Marketing\', 1, \'Marketing Spend\', IFNULL(Marketing_Spend,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 5, \'Marketing\', 2, \'Agency Spend\', IFNULL(Agency_Spend,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 5, \'Marketing\', 3, \'Influencer Spend\', IFNULL(Influencer_Spend,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 5, \'Marketing\', 4, \'Content Spend\', IFNULL(Content_Spend,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 5, \'Marketing\', 5, \'Total Marketing\', ( IFNULL(Marketing_Spend,0) + IFNULL(Agency_Spend,0) + IFNULL(Influencer_Spend,0) + IFNULL(Content_Spend,0) ) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 6, \'Retention\', 1, \'CRM & Retention\', IFNULL(CRM_Retention_Cost,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 7, \'Logistics II\', 1, \'RTO Charge\', IFNULL(RTO_Charge,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 7, \'Logistics II\', 2, \'Porter Charges\', IFNULL(Porter_logistic_cost,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 7, \'Logistics II\', 3, \'Total Logistics II\', ( IFNULL(RTO_Charge,0) + IFNULL(Porter_logistic_cost,0) ) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 8, \'CM2\', 1, \'CM2\', IFNULL(CM2,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 8, \'CM2\', 2, \'CM2%\', SAFE_DIVIDE( SUM(IFNULL(CM2,0)), NULLIF(SUM(IFNULL(Net_Sales,0)),0) ) * 100 AS value FROM Maplemonk.Atovio_Profit_Loss_New GROUP BY 1 UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 9, \'Webapp & Growth\', 1, \'Website Growth\', IFNULL(Website_Growth_Spend,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 10, \'Software & Tools\', 1, \'Software Spend\', IFNULL(Software_Spend,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 11, \'CM3\', 1, \'Net Margin (CM3)\', IFNULL(CM3,0) FROM Maplemonk.Atovio_Profit_Loss_New UNION ALL SELECT DATE_TRUNC(order_Date, MONTH) AS order_Date, 11, \'CM3\', 2, \'Net Margin (CM3%)\', SAFE_DIVIDE( SUM(IFNULL(CM3,0)), NULLIF(SUM(IFNULL(Net_Sales,0)),0) ) * 100 AS value FROM Maplemonk.Atovio_Profit_Loss_New GROUP BY 1 ) GROUP BY 1,2,3,4,5 ORDER BY order_Date DESC, main_category_sort, sub_category_sort;",
                    "transaction": true
